INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,stock,approved,active,source_shop,source_url) VALUES('TS0301','Beauty of Joseon','Revive Eye Serum Ginseng + Retinal','البشرة','العناية بالعين والرموش','امنحي محيط عينيكِ اهتمامًا يشبهكِ مع سيروم ريفايف من بيوتي أوف جوسون بالجنسنغ والريتينال. خطوة صغيرة في روتين المساء، تُوزّع بلطف قبل المرطب لترافق إطلالتكِ المرتاحة والمشرقة.','{"nameAr":"سيروم ريفايف للعين بالجنسنغ والريتينال من بيوتي أوف جوسون","tagline":"دلّلي نظرتكِ بلحظة عناية هادئة.","benefits":["عناية لمحيط العين","تركيبة بالجنسنغ والريتينال","عبوة 30 مل"],"howToUse":"ابدئي مساءً بكمية صغيرة وربتي بلطف حول عظمة محيط العين، بعيدًا عن العين وخط الرموش. أدخليه بالتدرج واتبعي تعليمات العبوة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. يحتوي على ريتينويد؛ يُتجنب أثناء الحمل والرضاعة، مع واقي شمس صباحًا واستشارة المختص عند الحاجة.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"eye-care","size":"30 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27-b","imageEditedWithAI":false}',14000,9990,28,'/images/catalog/TS0301-9dca9c20ce4b.webp',24,1,1,'Owner intake 2026-10-27-b','https://glowceryjo.com/products/beauty-of-joseon-revive-eye-serum') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,stock,approved,active,source_shop,source_url) VALUES('TS0302','AXIS-Y','Cera-Heart My Type Duo Cream','البشرة','المرطبات والكريمات','لا تحتاج كل مناطق الوجه الإحساس نفسه؛ كريم سيرا هارت ديو من أكسيس واي يجمع قوامين في عبوة واحدة. اختاري لكل منطقة ما يلائمها، واستمتعي بطقس ترطيب مرن يترك بشرتكِ بملمس ناعم ومريح.','{"nameAr":"كريم سيرا هارت ماي تايب ديو من أكسيس واي","tagline":"ترطيب على مقاس يومكِ وبشرتكِ.","benefits":["قوامان في عبوة واحدة","توزيع مختلف بحسب منطقة الوجه","حجم 60 مل"],"howToUse":"وزعي كمية مناسبة على بشرة نظيفة بعد السيروم، ودلكي برفق. عدّلي الكمية بحسب احتياج بشرتكِ وإرشادات العبوة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"moisturizer","size":"60 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27-b","imageEditedWithAI":false}',16000,11990,25,'/images/catalog/TS0302-d1b06ed7b971.webp',24,1,1,'Owner intake 2026-10-27-b','https://www.strawberrynet.com/id-ID/axis-y-cera-heart-my-type-duo-cream-60ml-2-02oz/322705?srsltid=AfmBOophhkj3Ap3v_P27d1bePodhu2lJYyoT-Jgy2ECAx2AEnXLQ0sYi') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,stock,approved,active,source_shop,source_url) VALUES('TS0303','Balance Active Formula','The Mighty Three Serum Set','البشرة','السيروم','اجعلي ترتيب روتينكِ أسهل مع مجموعة ذا مايتي ثري من بالانس: ثلاثة سيرومات، كل منها بحجم 30 مل. مجموعة تجمع خطوات متنوعة للعناية، لتختاري فيتامين C أو النياسيناميد أو الهيالورونيك بحسب احتياج بشرتكِ وإرشادات كل عبوة.','{"nameAr":"مجموعة ذا مايتي ثري من بالانس — 3 سيرومات","tagline":"ثلاث لحظات عناية، في هدية لنفسكِ.","benefits":["مجموعة كاملة من 3 سيرومات","30 مل لكل سيروم","اختيارات لتنويع روتين العناية"],"howToUse":"اختاري سيرومًا بحسب احتياج بشرتكِ وإرشادات كل عبوة، ووزعي كمية صغيرة قبل المرطب. أدخلي كل سيروم على حدة واتبعي واقي الشمس صباحًا.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"serum","size":"3 × 30 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27-b","imageEditedWithAI":false}',20000,14990,25,'/images/catalog/TS0303-c1c6a8b0ad84.webp',24,1,1,'Owner intake 2026-10-27-b','https://www.onbuy.com/gb/p/balance-active-formula-the-mighty-three-breakthrough-active-ingredients-for-visible-results-three-targeted-serums-that-you-can-layer-together-or~p56069273/') ON CONFLICT(id) DO NOTHING;
