INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,stock,approved,active,source_shop,source_url) VALUES('TS0332','SADOER','Strawberry Moisture Foot Mask','الجسم','العناية بالقدمين','ماسك القدمين بالفراولة من سادور، في العبوة المصوّرة على شكل قدم، دعوة لوقت هادئ بعد يوم من الحركة. اتبعي مدة الاستخدام المكتوبة على العبوة واستمتعي بخطوة عناية تهتم بملمس القدمين وراحتهما.','{"nameAr":"ماسك القدمين المرطب بالفراولة من سادور","tagline":"امنحي قدميكِ استراحة بنكهة الدلال.","benefits":["ماسك مخصص للقدمين","نسخة الفراولة","لحظة عناية منزلية"],"howToUse":"ضعي الماسك على قدمين نظيفتين وجافتين. التزمي بمدة الاستخدام وإرشادات العبوة، ثم أكملي العناية حسب التعليمات.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"foot-care","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27-b","imageEditedWithAI":true}',3000,1490,50,'/images/catalog/TS0332-44cdd21a976a.webp',24,1,1,'Owner intake 2026-10-27-b','owner-supplied:IMG_0420.jpeg') ON CONFLICT(id) DO NOTHING;
