INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,stock,approved,active,source_shop,source_url) VALUES('TS0339','Hismile','V34 Colour Corrector Serum','الجسم','العناية بالفم','مصحح اللون البنفسجي V34 من هاي سمايل بعبوة 30 مل مخصص لتحسين مظهر لون الابتسامة بصورة تجميلية مؤقتة. اتبعي تعليمات العبوة، واحتفظي بتنظيف الأسنان اليومي كخطوة أساسية؛ ليس تبييضًا دائمًا أو علاجًا للأسنان.','{"nameAr":"سيروم تصحيح مظهر لون الأسنان V34 من هاي سمايل","tagline":"لمسة تجميلية تكمل ابتسامتكِ.","benefits":["تصحيح تجميلي مؤقت لمظهر اللون","صيغة بنفسجية","عبوة 30 مل"],"howToUse":"اتبعي تعليمات العبوة للكمية وطريقة الاستعمال. لا تبتلعي المنتج، ولا تجعليه بديلًا عن تنظيف الأسنان المعتاد.","notes":"لا يُبتلع. اتبعي تعليمات العبوة والقيود العمرية، وتوقفي عند التهيج. لا يغني عن تنظيف الأسنان أو مراجعة طبيب الأسنان.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"oral-care","size":"30 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27-b","imageEditedWithAI":true}',12000,7990,33,'/images/catalog/TS0339-1b56ed5a6c82.webp',24,1,1,'Owner intake 2026-10-27-b','owner-supplied:IMG_0420.jpeg') ON CONFLICT(id) DO NOTHING;
