INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,stock,approved,active,source_shop,source_url) VALUES('TS0347','SHEGLAM','Complexion Pro Long Lasting Breathable Matte Foundation','المكياج','كريم الأساس','كريم أساس كومبليكشن برو من شيغلام يفتح لكِ مساحة لبناء إطلالتكِ المفضلة. ابدئي بطبقة رقيقة وادمجي من وسط الوجه إلى الخارج، ثم حددي مستوى بشرتكِ من الخيارات الأربعة ليصل طلبكِ باختيار واضح.','{"nameAr":"كريم أساس كومبلكشن برو المات من شيغلام","tagline":"قاعدة تشبهكِ، ولمسة تبدأ باختياركِ.","benefits":["كريم أساس للوجه","تغطية تُبنى بالتدريج","4 مستويات للبشرة للاختيار"],"howToUse":"حضّري البشرة بالمرطب، ثم ادمجي طبقة رقيقة بفرشاة أو إسفنجة نظيفة من وسط الوجه إلى الخارج. زيدي التغطية بالتدريج.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"foundation","size":"","shade":"","variantNote":"اختاري مستوى بشرتكِ من 1 إلى 4؛ التصنيف تقريبي للمتجر، وليس أكواد الشركة. صورة العبوة توضيحية.","introductoryOffer":true,"intakeBatch":"2026-10-27-b","imageEditedWithAI":false}',12000,8990,25,'/images/catalog/TS0347-5bee95e54b0b.webp',24,1,1,'Owner intake 2026-10-27-b','https://perfectobd.com/product/sheglam-complexion-pro-long-lasting-breathable-matte-foundation-1050') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,stock,approved,active,source_shop,source_url) VALUES('TS0348','La Roche-Posay','Retinol B3 Serum','البشرة','السيروم','سيروم ريتينول B3 من لاروش بوزيه بعبوة 30 مل يرافق روتين العناية المسائي. ابدئي بالتدرج مع الترطيب، وامنحي بشرتكِ وقتًا للتأقلم؛ استخدمي واقي الشمس صباحًا وتجنبي الجمع العشوائي مع المقشرات.','{"nameAr":"سيروم ريتينول B3 من لاروش بوزيه","tagline":"وقت المساء، ولحظة عناية مدروسة.","benefits":["سيروم ريتينول للعناية المسائية","إدخال تدريجي للروتين","عبوة 30 مل"],"howToUse":"مساءً، وزعي 3–4 قطرات على الوجه والرقبة بعيدًا عن العينين. ابدئي بوتيرة قليلة وأكملي بالمرطب؛ استخدمي واقي الشمس صباحًا.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. يحتوي على ريتينويد؛ يُتجنب أثناء الحمل والرضاعة، مع واقي شمس صباحًا واستشارة المختص عند الحاجة.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"serum","size":"30 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27-b","imageEditedWithAI":false}',20000,14990,25,'/images/catalog/TS0348-a96e219c9234.webp',24,1,1,'Owner intake 2026-10-27-b','https://www.sasa.com.hk/SalePage/index/407699?lang=en-US') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,stock,approved,active,source_shop,source_url) VALUES('TS0349','La Roche-Posay','Pure Vitamin C10 Serum','البشرة','السيروم','سيروم بيور فيتامين C10 من لاروش بوزيه بعبوة 30 مل خطوة عناية قبل المرطب وواقي الشمس. وزعي كمية صغيرة على البشرة النظيفة، وامنحي يومكِ بداية مرتبة؛ تحفظ العبوة بعيدًا عن الحرارة والضوء.','{"nameAr":"سيروم بيور فيتامين C10 من لاروش بوزيه","tagline":"قطرات صباحية تكمّل روتين إشراقتكِ.","benefits":["سيروم من مجموعة Pure C10","يُستخدم قبل المرطب","عبوة 30 مل"],"howToUse":"وزعي كمية صغيرة على البشرة النظيفة قبل المرطب، بعيدًا عن العينين. اتبعي وتيرة الاستخدام المكتوبة على العبوة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"serum","size":"30 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27-b","imageEditedWithAI":false}',20000,14990,25,'/images/catalog/TS0349-6625abab3ee2.webp',24,1,1,'Owner intake 2026-10-27-b','https://www.my-origines.com/nl/pure-vitamin-c10-P0964007.html') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,stock,approved,active,source_shop,source_url) VALUES('TS0350','La Roche-Posay','Effaclar Ultra Concentrated Serum','البشرة','السيروم','سيروم إيفاكلار ألترا كونسنتريتد من لاروش بوزيه بعبوة 30 مل يحتوي أحماضًا مقشرة ضمن خطوة عناية مسائية. ابدئي بوتيرة قليلة حسب ملاءمة بشرتكِ وتعليمات العبوة، وأكملي بالمرطب وواقي الشمس صباحًا.','{"nameAr":"سيروم إيفاكلار ألترا كونسنتريتد من لاروش بوزيه","tagline":"روتين مسائي يهتم بتفاصيل بشرتكِ.","benefits":["سيروم مقشر للعناية المسائية","من مجموعة Effaclar","عبوة 30 مل"],"howToUse":"يُستخدم مساءً على بشرة نظيفة وجافة بعيدًا عن العينين. ابدئي بوتيرة قليلة واتبعي تعليمات العبوة، ثم أكملي بالمرطب وواقي الشمس صباحًا.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. يحتوي أحماضًا مقشرة؛ لا تجمعيه في الروتين نفسه مع مقشرات أخرى أو ريتينويد دون إرشاد مختص.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"serum","size":"30 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27-b","imageEditedWithAI":false}',20000,14990,25,'/images/catalog/TS0350-0b4345caa60c.webp',24,1,1,'Owner intake 2026-10-27-b','https://skinvanity.com.mx/products/la-roche-posay-effaclar-serum-ultra-concentrated-peeling-anti-imperfecciones') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,stock,approved,active,source_shop,source_url) VALUES('TS0351','Garnier','SkinActive Micellar Cleansing Water','البشرة','الغسول والتنظيف','ماء ميسيلار غارنييه بالغطاء الوردي بعبوة 400 مل خطوة عملية لإزالة المكياج وتنظيف البشرة. بللي قطعة قطن وامسحي برفق دون فرك قاسٍ؛ بداية بسيطة لروتين المساء الذي تستحقينه.','{"nameAr":"ماء ميسيلار سكين أكتيف من غارنييه","tagline":"أزيلي تفاصيل اليوم، واحتفظي بلحظة لكِ.","benefits":["ماء ميسيلار لإزالة المكياج","تطبيق بالقطن","عبوة 400 مل"],"howToUse":"بللي قطنة وامسحي البشرة بلطف دون فرك. اتبعي تعليمات العبوة الخاصة بمنطقة العين والشطف، ثم أكملي روتينكِ.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"cleanser","size":"400 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27-b","imageEditedWithAI":false}',7000,4990,28,'/images/catalog/TS0351-09e8b9f91e1d.webp',24,1,1,'Owner intake 2026-10-27-b','https://www.rubyzcosmetics.com/products/garnier-micellar-water-cleanser-and-daily-make-up-remover-400-ml') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,stock,approved,active,source_shop,source_url) VALUES('TS0352','Garnier','Micellar Cleansing Rose Water','البشرة','الغسول والتنظيف','ماء الميسيلار بالورد من غارنييه بعبوة 400 مل يجمع خطوة إزالة المكياج مع إحساس لطيف بالعناية. مرري قطنة مبللة برفق على البشرة، وخذي لحظتكِ قبل إكمال روتين التنظيف والترطيب المفضل لديكِ.','{"nameAr":"ماء ميسيلار الورد من غارنييه","tagline":"انتعاش الورد في بداية روتينكِ.","benefits":["نسخة ماء الورد","تنظيف وإزالة للمكياج","عبوة 400 مل"],"howToUse":"بللي قطنة وامسحي البشرة بلطف دون فرك. اتبعي تعليمات العبوة الخاصة بمنطقة العين والشطف، ثم أكملي روتينكِ.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"cleanser","size":"400 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27-b","imageEditedWithAI":false}',8000,5990,25,'/images/catalog/TS0352-2020e06245e7.webp',24,1,1,'Owner intake 2026-10-27-b','https://alamerbeauty.com/ar/%D9%85%D8%B2%D9%8A%D9%84-%D9%85%D9%83%D9%8A%D8%A7%D8%AC-%D9%85%D9%86-%D9%85%D8%A7%D8%B1%D9%83%D8%A9-%D8%BA%D8%A7%D8%B1%D9%86%D9%8A%D9%8A%D9%87-%D9%85%D9%8A%D8%B3%D9%8A%D9%84%D8%A7%D8%B1-%D8%A8%D9%85%D8%A7%D8%A1-%D8%A7%D9%84%D9%88%D8%B1%D8%AF-400%D9%85%D9%84/p1935231291') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,stock,approved,active,source_shop,source_url) VALUES('TS0353','Maybelline','Mascara Fuchsia Photographed Edition','المكياج','المسكارا','ماسكارا ميبيلين بالعبوة الوردية الفاقعة تضيف إلى مكياجكِ خطوة لإبراز الرموش وتحديدها. وزعيها بطبقات خفيفة من الجذور إلى الأطراف، وامنحي الزوايا الخارجية اهتمامًا إضافيًا لتكملي نظرتكِ باللمسة التي تحبينها.','{"nameAr":"ماسكارا ميبيلين — العبوة الوردية المصوّرة","tagline":"وردي جريء، ولمسة تبرز نظرتكِ.","benefits":["ماسكارا لتحديد الرموش","تطبيق متدرج بالطبقات","العبوة الوردية المصوّرة"],"howToUse":"مرري الفرشاة من جذور الرموش إلى الأطراف بحركات خفيفة. أضيفي طبقة عند الحاجة، وأزيلي المكياج بلطف مساءً.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"mascara","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27-b","imageEditedWithAI":true}',12000,8990,25,'/images/catalog/TS0353-ac2caf9b08a9.webp',24,1,1,'Owner intake 2026-10-27-b','owner-supplied:IMG_0421.jpeg') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,stock,approved,active,source_shop,source_url) VALUES('TS0354','Plump it!','Volumising Lip Plumper Sponge Tip Click Applicator','المكياج','الشفاه','ليب بلامبر من بلامب إت بفرشاة إسفنجية يضيف خطوة لامعة إلى مكياج الشفاه. ابدئي بكمية قليلة على شفاه سليمة واتّبعي تعليمات العبوة؛ قد يسبب إحساسًا بالوخز، ولا يضمن تكبيرًا دائمًا للشفاه.','{"nameAr":"ليب بلامبر بفرشاة إسفنجية من بلامب إت","tagline":"لمسة غلوس، وشفاه بإطلالة أجرأ.","benefits":["فرشاة إسفنجية للتطبيق","لمسة تجميلية للشفاه","كمية صغيرة قابلة للتوزيع"],"howToUse":"ضعي كمية قليلة على شفاه سليمة وجافة، ثم وزعي بلطف بحسب تعليمات العبوة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. قد يسبب الوخز؛ توقفي عند الألم أو التورم أو التهيج، ولا تضعيه على شفاه متشققة.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"lips","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27-b","imageEditedWithAI":false}',6000,3990,33,'/images/catalog/TS0354-5fcabbd7a10b.webp',24,1,1,'Owner intake 2026-10-27-b','https://www.plump-it.com/collections/plump-it-volumising-lip-plumper') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,stock,approved,active,source_shop,source_url) VALUES('TS0355','L''Oreal Paris','Infallible Full Wear Concealer','المكياج','الكونسيلر','كونسيلر إنفاليبل فول وير من لوريال يساعدكِ على توحيد مظهر المناطق التي تريدين تغطيتها. ضعي نقاطًا صغيرة وادمجي بلطف دون مبالغة في الكمية؛ أكدي الدرجة المتاحة مع المتجر لتكملي إطلالتكِ باختيار مناسب.','{"nameAr":"كونسيلر إنفاليبل فول وير من لوريال","tagline":"تفاصيل مرتبة لقاعدة مكياج تحبينها.","benefits":["كونسيلر سائل","تطبيق موضعي بنقاط صغيرة","تغطية تُبنى بالتدريج"],"howToUse":"ضعي نقاطًا صغيرة على المناطق المطلوبة وادمجي بلطف بإسفنجة أو فرشاة نظيفة، بعيدًا عن داخل العين.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"concealer","size":"","shade":"","variantNote":"أكدي درجة الكونسيلر المتاحة مع المتجر قبل تثبيت الطلب.","introductoryOffer":true,"intakeBatch":"2026-10-27-b","imageEditedWithAI":false}',12000,8990,25,'/images/catalog/TS0355-5e645a7dfbc7.webp',24,1,1,'Owner intake 2026-10-27-b','https://www.newu.in/products/loreal-paris-infallible-full-wear-more-than-concealer-309-10ml') ON CONFLICT(id) DO NOTHING;
