INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,stock,approved,active,source_shop,source_url) VALUES('TS0357','PanOxyl','Acne Foaming Wash Benzoyl Peroxide 10%','البشرة','الغسول والتنظيف','غسول بانوكسيل الرغوي بتركيز 10% بنزويل بيروكسيد، عبوة 156 غرامًا، يختلف عن نسخة 4% الموجودة في المتجر. اختاريه وفق تعليمات العبوة وتوجيه المختص عند الحاجة، وامنحي البشرة ترطيبًا واهتمامًا منتظمًا.','{"nameAr":"غسول بان أوكسيل الرغوي بنزويل بيروكسيد 10%","tagline":"خطوة تنظيف مركزة ضمن روتين مدروس.","benefits":["تركيز 10% بنزويل بيروكسيد","غسول يُشطف بالماء","عبوة 156 غرامًا"],"howToUse":"بللي المنطقة ودلكي بلطف لمدة دقيقة إلى دقيقتين ثم اشطفي وجففي. ابدئي مرة يوميًا، وخففي الوتيرة عند الجفاف وفق تعليمات العبوة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. قد يسبب جفافًا أو تهيجًا ويبهت الأقمشة. تجنبي العينين والشفاه والجلد المتشقق؛ استشيري مختصًا عند الحمل أو العلاج الجلدي أو الحساسية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"cleanser","size":"156 g","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27-b","imageEditedWithAI":false}',14000,9990,28,'/images/catalog/TS0357-7a60f2cff083.webp',24,1,1,'Owner intake 2026-10-27-b','https://www.colorshow.pk/products/panoxyl-acne-foaming-wash-benzoyl-peroxide-10-maximum-strength') ON CONFLICT(id) DO NOTHING;
