INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,stock,approved,active,source_shop,source_url) VALUES('TS0359','Bioderma','Photoderm SPF100 Invisible Body Sun Milk','الجسم','واقي شمس الجسم','حليب الشمس غير الملون للجسم من بيوديرما فوتوديرم، بالعلبة البيضاء المكتوب عليها SPF100 وحجم 100 مل. وزعيه بكمية كافية قبل التعرض للشمس وجدديه حسب الإرشادات؛ هذا إصدار الجسم غير الملون، منفصل عن النسخة الملونة.','{"nameAr":"حليب الشمس غير الملون للجسم من بيوديرما فوتوديرم","tagline":"عناية شمس للجسم ترافق أيامكِ المشرقة.","benefits":["حليب شمس مخصص للجسم","إصدار غير ملون","SPF100 وحجم 100 مل بحسب العبوة"],"howToUse":"وزعي بكمية كافية على مناطق الجسم المكشوفة قبل التعرض للشمس، وجددي كل ساعتين وبعد السباحة أو التعرق أو التجفيف.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"body-sunscreen","size":"100 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27-b","imageEditedWithAI":true}',18000,13500,25,'/images/catalog/TS0359-7c26f4407b60.webp',24,1,1,'Owner intake 2026-10-27-b','owner-supplied:IMG_0421.jpeg') ON CONFLICT(id) DO NOTHING;
